import Foundation
import SwiftData
import UserNotifications
import UIKit

@MainActor final class NotificationService {
    private let center = UNUserNotificationCenter.current()
    func requestIfNeeded() async { _ = try? await center.requestAuthorization(options: [.alert, .sound, .badge]) }
    func refresh(container: ModelContainer) async { center.removeAllPendingNotificationRequests(); let context = ModelContext(container); let tasks = (try? context.fetch(FetchDescriptor<TaskItem>())) ?? []; for task in tasks where !task.isCompleted { if let date = task.reminderDate, date > .now { let content = UNMutableNotificationContent(); content.title = "Neaizmirsti par savu lietiņu! 🌸"; content.body = task.title; content.sound = .default; let req = UNNotificationRequest(identifier: task.id.uuidString, content: content, trigger: UNCalendarNotificationTrigger(dateMatching: Calendar.current.dateComponents([.year,.month,.day,.hour,.minute], from: date), repeats: false)); try? await center.add(req) } }; await scheduleMorningSummary(tasks: tasks) }
    private func scheduleMorningSummary(tasks: [TaskItem]) async { let content = UNMutableNotificationContent(); content.title = "Labrīt, Vika! 🌸"; let count = tasks.filter { Calendar.current.isDateInToday($0.dueDate) && !$0.isCompleted }.count; content.body = "Šodien Tev ir \(count) lietiņas, ko paveikt. Lai jauka diena!"; content.sound = .default; var c = DateComponents(); c.hour = UserDefaults.standard.object(forKey: "summaryHour") as? Int ?? 8; c.minute = UserDefaults.standard.object(forKey: "summaryMinute") as? Int ?? 0; try? await center.add(UNNotificationRequest(identifier: "morning-summary", content: content, trigger: UNCalendarNotificationTrigger(dateMatching: c, repeats: true))) }
    func openSettings() { guard let url = URL(string: UIApplication.openSettingsURLString) else { return }; UIApplication.shared.open(url) }
}

@MainActor final class BackupService {
    struct Envelope: Codable { var schemaVersion: Int = 1; var createdAt: Date; var appVersion: String = "1.0"; var tasks: [TaskDTO]; var notes: [NoteDTO]; var habits: [HabitDTO]; var entries: [EntryDTO]; var goals: [GoalDTO]; var events: [EventDTO] }
    struct TaskDTO: Codable { var id: UUID; var title: String; var details: String; var dueDate: Date; var dueTime: Date?; var isCompleted: Bool; var priorityRaw: String; var category: String; var reminderDate: Date?; var repeatRule: String; var createdAt: Date; var completedAt: Date? }
    struct NoteDTO: Codable { var id: UUID; var title: String; var content: String; var category: String; var color: String; var createdAt: Date; var updatedAt: Date; var isPinned: Bool; var isShoppingList: Bool }
    struct HabitDTO: Codable { var id: UUID; var title: String; var frequencyRaw: String; var createdAt: Date; var isActive: Bool }; struct EntryDTO: Codable { var id: UUID; var habitID: UUID; var date: Date; var isCompleted: Bool }; struct GoalDTO: Codable { var id: UUID; var title: String; var goalDescription: String; var targetDate: Date?; var progress: Double; var category: String }; struct EventDTO: Codable { var id: UUID; var title: String; var startDate: Date; var endDate: Date; var location: String; var reminderDate: Date?; var repeatRule: String }
    private var folder: URL? { UserDefaults.standard.url(forKey: "backupFolder") }
    func checkDailyBackup(container: ModelContainer) async { guard UserDefaults.standard.object(forKey: "autoBackup") as? Bool ?? true, let folder else { return }; let name = "backup-\(ISO8601DateFormatter().string(from: .now).prefix(10)).json"; guard !FileManager.default.fileExists(atPath: folder.appendingPathComponent(name).path) else { return }; _ = try? create(container: container, in: folder) }
    func create(container: ModelContainer, in folder: URL? = nil) throws -> URL { let dir = folder ?? self.folder ?? FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]; try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true); let c = ModelContext(container); let e = Envelope(createdAt: .now, tasks: (try c.fetch(FetchDescriptor<TaskItem>())).map { TaskDTO(id:$0.id,title:$0.title,details:$0.details,dueDate:$0.dueDate,dueTime:$0.dueTime,isCompleted:$0.isCompleted,priorityRaw:$0.priorityRaw,category:$0.category,reminderDate:$0.reminderDate,repeatRule:$0.repeatRule,createdAt:$0.createdAt,completedAt:$0.completedAt) }, notes: (try c.fetch(FetchDescriptor<Note>())).map { NoteDTO(id:$0.id,title:$0.title,content:$0.content,category:$0.category,color:$0.color,createdAt:$0.createdAt,updatedAt:$0.updatedAt,isPinned:$0.isPinned,isShoppingList:$0.isShoppingList) }, habits: (try c.fetch(FetchDescriptor<Habit>())).map { HabitDTO(id:$0.id,title:$0.title,frequencyRaw:$0.frequencyRaw,createdAt:$0.createdAt,isActive:$0.isActive) }, entries: (try c.fetch(FetchDescriptor<HabitEntry>())).map { EntryDTO(id:$0.id,habitID:$0.habitID,date:$0.date,isCompleted:$0.isCompleted) }, goals: (try c.fetch(FetchDescriptor<Goal>())).map { GoalDTO(id:$0.id,title:$0.title,goalDescription:$0.goalDescription,targetDate:$0.targetDate,progress:$0.progress,category:$0.category) }, events: (try c.fetch(FetchDescriptor<CalendarEvent>())).map { EventDTO(id:$0.id,title:$0.title,startDate:$0.startDate,endDate:$0.endDate,location:$0.location,reminderDate:$0.reminderDate,repeatRule:$0.repeatRule) }); let data = try JSONEncoder.backup.encode(e); let url = dir.appendingPathComponent("backup-\(ISO8601DateFormatter().string(from: .now).prefix(10)).json"); try data.write(to: url, options: .atomic); guard (try? JSONDecoder.backup.decode(Envelope.self, from: data)) != nil else { throw CocoaError(.fileReadCorruptFile) }; retainLatest(in: dir); UserDefaults.standard.set(Date(), forKey: "lastBackup"); return url }
    func restore(from url: URL, container: ModelContainer) throws { let data = try Data(contentsOf: url); let e = try JSONDecoder.backup.decode(Envelope.self, from: data); guard e.schemaVersion == 1 else { throw CocoaError(.fileReadCorruptFile) }; let c = ModelContext(container); let taskIDs = Set((try c.fetch(FetchDescriptor<TaskItem>())).map(\.id)); for x in e.tasks where !taskIDs.contains(x.id) { let v = TaskItem(title:x.title,dueDate:x.dueDate,details:x.details,priority:TaskPriority(rawValue:x.priorityRaw) ?? .medium,category:x.category,dueTime:x.dueTime,reminderDate:x.reminderDate,repeatRule:x.repeatRule); v.isCompleted=x.isCompleted; v.completedAt=x.completedAt; v.id=x.id; c.insert(v) }; let noteIDs = Set((try c.fetch(FetchDescriptor<Note>())).map(\.id)); for x in e.notes where !noteIDs.contains(x.id) { let v=Note(title:x.title,content:x.content,category:x.category,color:x.color,isShoppingList:x.isShoppingList); v.id=x.id; v.createdAt=x.createdAt; v.updatedAt=x.updatedAt; v.isPinned=x.isPinned; c.insert(v) }; let habitIDs = Set((try c.fetch(FetchDescriptor<Habit>())).map(\.id)); for x in e.habits where !habitIDs.contains(x.id) { let v=Habit(title:x.title,frequency:HabitFrequency(rawValue:x.frequencyRaw) ?? .daily); v.id=x.id; v.createdAt=x.createdAt; v.isActive=x.isActive; c.insert(v) }; let entryIDs = Set((try c.fetch(FetchDescriptor<HabitEntry>())).map(\.id)); for x in e.entries where !entryIDs.contains(x.id) { let v=HabitEntry(habitID:x.habitID,date:x.date,isCompleted:x.isCompleted); v.id=x.id; c.insert(v) }; let goalIDs = Set((try c.fetch(FetchDescriptor<Goal>())).map(\.id)); for x in e.goals where !goalIDs.contains(x.id) { let v=Goal(title:x.title,description:x.goalDescription,targetDate:x.targetDate,category:x.category); v.id=x.id; v.progress=x.progress; c.insert(v) }; let eventIDs = Set((try c.fetch(FetchDescriptor<CalendarEvent>())).map(\.id)); for x in e.events where !eventIDs.contains(x.id) { let v=CalendarEvent(title:x.title,startDate:x.startDate,endDate:x.endDate,location:x.location,reminderDate:x.reminderDate); v.id=x.id; v.repeatRule=x.repeatRule; c.insert(v) }; try c.save() }
    private func retainLatest(in dir: URL) { guard let files = try? FileManager.default.contentsOfDirectory(at: dir, includingPropertiesForKeys: [.creationDateKey]).filter({ $0.pathExtension == "json" }).sorted(by: { $0.lastPathComponent > $1.lastPathComponent }), files.count > 30 else { return }; for file in files.dropFirst(30) { try? FileManager.default.removeItem(at: file) } }
}
extension JSONEncoder { static var backup: JSONEncoder { let e = JSONEncoder(); e.dateEncodingStrategy = .iso8601; return e } }; extension JSONDecoder { static var backup: JSONDecoder { let d = JSONDecoder(); d.dateDecodingStrategy = .iso8601; return d } }
